/bin/bash -lc "python - <<'PY'
import json, numpy as np
from pathlib import Path
from model import mode_fields, amplitudes, quadrature, DAMPING
records=json.loads(Path('/app/data/calibration.json').read_text())
def calc(e,p):
 n,w=quadrature(32); lo,hi=np.array(e['window'])*e['thickness']; z=(lo+hi)/2+(hi-lo)*n/2
 f=mode_fields(z,e,p)@amplitudes(e,p); om=e['frequency']; loss=DAMPING*p*p/(om*om+DAMPING*DAMPING)*np.sum(abs(f[:,:2])**2,axis=1)
 return (hi-lo)*np.dot(w,loss)/(2*np.cos(e['angle']))
def obj(p): return sum(((calc(r['input'],p)-r['value'])/1e-5)**2 for r in records)
ps=np.linspace(.85,1.15,61); vals=np.array([obj(p) for p in ps]);
for p,v in zip(ps,vals):
 if v==vals.min() or v < 1e5: print(p,v)
PY"
